import type { LedgerRow } from '../../types'

// Salidas reales de ./bin/sdd-ai en la rama feature/mods-salidas-legibles, capturadas el 2026-10-03 desde
// el commit base con los cambios del flujo sin commitear: el comando, stdout, stderr, el código del proceso,
// el commit y la versión de Claude Code instalada. Los tests no leen los artefactos del flujo. Las rutas
// absolutas del checkout donde se capturaron van como `<repo>`.

export type CapturedLedgerRow = LedgerRow & { [field: string]: unknown }
export type CapturedReview = { id: string; state: string; ledger: CapturedLedgerRow[]; [field: string]: unknown }
export type BinaryCapture = {
  name: string
  command: string
  exitCode: number
  stdout: string
  stderr: string
  commit: string
  claudeCodeVersion: string
  captured: string
}

// Cada revisión es un subconjunto de su salida real, y lo dice en su nombre: conserva todos los campos y,
// del ledger, la primera entrada de cada combinación de revisor, estado y severidad, en su orden. Su stdout
// es ese objeto impreso como lo imprime el binario: JSON en una línea, con salto final.
const review = (capture: Omit<BinaryCapture, 'stdout'> & { value: CapturedReview }) => ({ ...capture, stdout: `${JSON.stringify(capture.value)}\n` })

